// ───────────────────────────── Euler ─────────────────────────────

/** Rotation matrix entries rIJ (1-based) of a column-major 4x4. */
const rot = (m) => { const e = m.elements; return (i, j) => e[(j - 1) * 4 + (i - 1)]; };
